"""The settings every wrapper's settings extend: `@zuke/core`'s tooling base.

Generated by ``zuke facades`` from the engine's tool spec; edit the wrapper in
zuke-build/zuke, not this file.
"""

from __future__ import annotations

from collections.abc import Mapping
from typing import Literal, Self

from zuke._facade import Settings


class ToolSettings(Settings):
    """Base settings for a command wrapper."""

    def env(self, record: Mapping[str, str]) -> Self:
        """Environment variables for the tool."""
        return self._record("env", record)

    def cwd(self, path: str) -> Self:
        """The working directory."""
        return self._record("cwd", path)

    def no_throw(self, on: bool | None = None) -> Self:
        """Do not throw on a non-zero exit."""
        return self._record("noThrow", on)

class SubcommandSettings(ToolSettings):
    """Settings of a tool with subcommands."""

    def flag(self, name: str, *values: Literal[True, 2] | str | float) -> Self:
        """A flag to pass."""
        return self._record("flag", name, *values)
